use xiom.io;

type Address = {
  street: Str;
  city: Str;
}

type Person = {
  name: Str;
  home: Address;
}

fn city_of(person: Person) -> Str {
  return person.home.city;
}

fn main() -> Int {
  let addr = Address{ street: "10 Downing St"; city: "London"; };
  let pm = Person{ name: "Prime Minister"; home: addr; };
  let city = pm.home.city;
  return 0;
}
